INSERT INTO routes (id, settings_version_id, route_key, display_name, aliases_json, complexity, curve_type, timing_modifier, release_pct, stem_pct, break_pct, sustain_pct, preview_shape_json) SELECT i.id, i.settings_version_id, i.route_key, i.display_name, i.aliases_json, i.complexity, i.curve_type, i.timing_modifier, i.release_pct, i.stem_pct, i.break_pct, i.sustain_pct, i.preview_shape_json FROM afl_remaining_19_0 i WHERE NOT EXISTS(SELECT 1 FROM routes t WHERE t.id=i.id);
INSERT INTO route_depths (id, settings_version_id, depth_key, display_name, sort_order, min_air_yards, max_air_yards, base_time_to_open) SELECT i.id, i.settings_version_id, i.depth_key, i.display_name, i.sort_order, i.min_air_yards, i.max_air_yards, i.base_time_to_open FROM afl_remaining_19_1 i WHERE NOT EXISTS(SELECT 1 FROM route_depths t WHERE t.id=i.id);
INSERT INTO route_depth_eligibility (settings_version_id, route_id, route_depth_id, is_available) SELECT i.settings_version_id, i.route_id, i.route_depth_id, i.is_available FROM afl_remaining_19_2 i WHERE NOT EXISTS(SELECT 1 FROM route_depth_eligibility t WHERE t.settings_version_id=i.settings_version_id AND t.route_id=i.route_id AND t.route_depth_id=i.route_depth_id);
INSERT INTO openness_curve_points (settings_version_id, curve_type, progress_fraction, openness_score) SELECT i.settings_version_id, i.curve_type, i.progress_fraction, i.openness_score FROM afl_remaining_19_3 i WHERE NOT EXISTS(SELECT 1 FROM openness_curve_points t WHERE t.settings_version_id=i.settings_version_id AND t.curve_type=i.curve_type AND t.progress_fraction=i.progress_fraction);
