-- 19-normalized-route-settings. Reviewed uploaded workbook only; save pending edits and back up first.
-- Run ENTIRE file in DB Browser, verify counts, then Write Changes.
-- SAVEPOINT supports an existing transaction. No records are replaced.
-- 19 routes, 9 depths, 171 eligibility pairs, 28 curve points; draft settings remain draft.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_19;
CREATE TEMP TABLE afl_remaining_19_0 AS SELECT id, settings_version_id, route_key, display_name, aliases_json, complexity, curve_type, timing_modifier, release_pct, stem_pct, break_pct, sustain_pct, preview_shape_json FROM routes WHERE 0;
CREATE TEMP TABLE afl_remaining_19_1 AS SELECT id, settings_version_id, depth_key, display_name, sort_order, min_air_yards, max_air_yards, base_time_to_open FROM route_depths WHERE 0;
CREATE TEMP TABLE afl_remaining_19_2 AS SELECT settings_version_id, route_id, route_depth_id, is_available FROM route_depth_eligibility WHERE 0;
CREATE TEMP TABLE afl_remaining_19_3 AS SELECT settings_version_id, curve_type, progress_fraction, openness_score FROM openness_curve_points WHERE 0;
CREATE TEMP TABLE afl_remaining_19_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_remaining_19_check BEFORE INSERT ON afl_remaining_19_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import 05 season first.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2) THEN RAISE(ROLLBACK,'Apply schema upgrade 10 first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_19_0 i JOIN routes t ON t.id=i.id WHERE t.settings_version_id IS NOT i.settings_version_id OR t.route_key IS NOT i.route_key OR t.display_name IS NOT i.display_name OR t.aliases_json IS NOT i.aliases_json OR t.complexity IS NOT i.complexity OR t.curve_type IS NOT i.curve_type OR t.timing_modifier IS NOT i.timing_modifier OR t.release_pct IS NOT i.release_pct OR t.stem_pct IS NOT i.stem_pct OR t.break_pct IS NOT i.break_pct OR t.sustain_pct IS NOT i.sustain_pct OR t.preview_shape_json IS NOT i.preview_shape_json) THEN RAISE(ROLLBACK,'routes: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_19_0 i JOIN routes t ON t.settings_version_id=i.settings_version_id AND t.route_key=i.route_key WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'routes: natural key uses another ID.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_19_1 i JOIN route_depths t ON t.id=i.id WHERE t.settings_version_id IS NOT i.settings_version_id OR t.depth_key IS NOT i.depth_key OR t.display_name IS NOT i.display_name OR t.sort_order IS NOT i.sort_order OR t.min_air_yards IS NOT i.min_air_yards OR t.max_air_yards IS NOT i.max_air_yards OR t.base_time_to_open IS NOT i.base_time_to_open) THEN RAISE(ROLLBACK,'route_depths: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_19_1 i JOIN route_depths t ON t.settings_version_id=i.settings_version_id AND t.depth_key=i.depth_key WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'route_depths: natural key uses another ID.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_19_2 i JOIN route_depth_eligibility t ON t.settings_version_id=i.settings_version_id AND t.route_id=i.route_id AND t.route_depth_id=i.route_depth_id WHERE t.is_available IS NOT i.is_available) THEN RAISE(ROLLBACK,'route_depth_eligibility: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_19_3 i JOIN openness_curve_points t ON t.settings_version_id=i.settings_version_id AND t.curve_type=i.curve_type AND t.progress_fraction=i.progress_fraction WHERE t.openness_score IS NOT i.openness_score) THEN RAISE(ROLLBACK,'openness_curve_points: existing record differs; no overwrite.') END;
END;
DROP TRIGGER afl_remaining_19_check;
DROP TABLE afl_remaining_19_guard;
DROP TABLE afl_remaining_19_0;
DROP TABLE afl_remaining_19_1;
DROP TABLE afl_remaining_19_2;
DROP TABLE afl_remaining_19_3;
RELEASE SAVEPOINT afl_remaining_19;
PRAGMA foreign_key_check;
SELECT 'routes' AS imported_table,count(*) AS reviewed_records_present FROM routes t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='861a578f-d1fa-5cfa-926c-580d5315fcc7' AND m.target_table='routes' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'route_depths' AS imported_table,count(*) AS reviewed_records_present FROM route_depths t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='861a578f-d1fa-5cfa-926c-580d5315fcc7' AND m.target_table='route_depths' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'route_depth_eligibility' AS imported_table,count(*) AS reviewed_records_present FROM route_depth_eligibility t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='861a578f-d1fa-5cfa-926c-580d5315fcc7' AND m.target_table='route_depth_eligibility' AND m.target_id=CAST(t.settings_version_id AS TEXT)||'|'||CAST(t.route_id AS TEXT)||'|'||CAST(t.route_depth_id AS TEXT))
UNION ALL
SELECT 'openness_curve_points' AS imported_table,count(*) AS reviewed_records_present FROM openness_curve_points t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='861a578f-d1fa-5cfa-926c-580d5315fcc7' AND m.target_table='openness_curve_points' AND m.target_id=CAST(t.settings_version_id AS TEXT)||'|'||CAST(t.curve_type AS TEXT)||'|'||CAST(t.progress_fraction AS TEXT));
